MAP
    NAME "SS_MAP_MCIR_MACROCIRCUITOS_GENERAL"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
            "wfs_getfeature_formatlist" "gml,geojson"
            "wfs_enable_request" "*"
            "gml_featureid" "gid"
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_macrocircuitos.log"
    DEBUG 0
    LAYER
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_MCIR_MACROCIRCUITOS_GENERAL"
        METADATA
            'ows_title' 'Macrocircuitos'
            'ows_include_items' 'all'
            'gml_include_items' 'all'
        END
        PROJECTION
            'init=epsg:32614'
        END #PROJECTION
        INCLUDE 'includes/conexion.map'
        DATA "geometry from macrocircuitos using unique gid using srid=32614"
        STATUS DEFAULT
        TYPE POLYGON
        LABELITEM "nommac"
        CLASS
            NAME "limite de macrocircuitos"
            LABEL
                SIZE 19
                COLOR 0 0 255
                OUTLINECOLOR 254 254 254
                TYPE TRUETYPE
                FONT "ARIAL"
            END
            STYLE
                COLOR [color]
                OUTLINECOLOR 0 0 255
            END #STYLE
        END #CLASS
    END #LAYER
END #MAP